package edu.unimagdalena.RCMU.domine.entity;import edu.unimagdalena.RCMU.domine.enums.OfficeStatus;import jakarta.persistence.*;import lombok.*;@Entity@Table(name = "offices")@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builderpublic class Office {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @Column(nullable = false, unique = true)    private String roomNumber;    @Column(nullable = false)    private String location;    @Enumerated(EnumType.STRING)    @Builder.Default    private OfficeStatus status = OfficeStatus.AVAILABLE;}